     1→/**
     2→ * CPUVisualizer - Coordinator component for CPU visualization
     3→ *
     4→ * Single entry point that:
     5→ * - Creates the complete visualization DOM structure
     6→ * - Initializes child view components (PipelineView, RegisterView, ExecutionView)
     7→ * - Listens to 'cpu:framechange' events from AnimationEngine
     8→ * - Delegates rendering to child components
     9→ *
    10→ * This is the only component that needs to be instantiated by the UI.
    11→ * Child views are managed internally.
    12→ *
    13→ * Usage:
    14→ *   const container = document.getElementById('cpu-viz-container');
    15→ *   const visualizer = new CPUVisualizer(container);
    16→ *   // Rendering happens automatically via cpu:framechange events
    17→ *   // Or manually: visualizer.render(cpuState);
    18→ */
    19→(function() {
    20→  'use strict';
    21→
    22→  class CPUVisualizer {
    23→    /**
    24→     * Creates a CPUVisualizer instance
    25→     * @param {HTMLElement} container - DOM element to render visualization into
    26→     */
    27→    constructor(container) {
    28→      this.container = container;
    29→      this.container.className = 'cpu-visualizer';
    30→
    31→      // Build the DOM structure
    32→      this._createDOM();
    33→
    34→      // Initialize child view components
    35→      this.pipelineView = new PipelineView(
    36→        this.container.querySelector('[data-pipeline-view]')
    37→      );
    38→      this.registerView = new RegisterView(
    39→        this.container.querySelector('[data-register-view]')
    40→      );
    41→      this.executionView = new ExecutionView(
    42→        this.container.querySelector('[data-execution-view]')
    43→      );
    44→
    45→      // Bind and register event listener for AnimationEngine events
    46→      this._handleFrameChange = this._handleFrameChange.bind(this);
    47→      window.addEventListener('cpu:framechange', this._handleFrameChange);
    48→    }
    49→
    50→    /**
    51→     * Creates the visualization DOM structure inside the container
    52→     * @private
    53→     */
    54→    _createDOM() {
    55→      this.container.innerHTML = `
    56→        <section class="pipeline-section">
    57→          <h2>Pipeline Stages</h2>
    58→          <div class="pipeline-stages" data-pipeline-view></div>
    59→        </section>
    60→        <aside class="data-section">
    61→          <section class="registers-section">
    62→            <h2>Registers</h2>
    63→            <div class="register-grid" data-register-view></div>
    64→          </section>
    65→          <section class="execution-section">
    66→            <h2>Execution State</h2>
    67→            <div data-execution-view aria-live="polite">
    68→              <p>Cycle: <span data-cycle-count>0</span></p>
    69→              <p>Instructions: <span data-instruction-count>0</span></p>
    70→            </div>
    71→          </section>
    72→        </aside>
    73→      `;
    74→    }
    75→
    76→    /**
    77→     * Handles cpu:framechange events from AnimationEngine
    78→     * @param {CustomEvent} event - Event with detail.state (CPUState)
    79→     * @private
    80→     */
    81→    _handleFrameChange(event) {
    82→      if (event.detail && event.detail.state) {
    83→        this.render(event.detail.state);
    84→      }
    85→    }
    86→
    87→    /**
    88→     * Renders the current CPU state to all child views
    89→     * Can be called manually or automatically via events
    90→     * @param {CPUState} state - Current CPU state to render
    91→     */
    92→    render(state) {
    93→      this.pipelineView.render(state);
    94→      this.registerView.render(state);
    95→      this.executionView.render(state);
    96→    }
    97→
    98→    /**
    99→     * Cleans up event listeners and DOM
   100→     * Call this when removing the visualizer
   101→     */
   102→    destroy() {
   103→      window.removeEventListener('cpu:framechange', this._handleFrameChange);
   104→      this.container.innerHTML = '';
   105→      this.pipelineView = null;
   106→      this.registerView = null;
   107→      this.executionView = null;
   108→    }
   109→  }
   110→
   111→  // Export to global scope (vanilla JS pattern)
   112→  if (typeof window !== 'undefined') {
   113→    window.CPUVisualizer = CPUVisualizer;
   114→  } else if (typeof global !== 'undefined') {
   115→    global.CPUVisualizer = CPUVisualizer;
   116→  }
   117→})();
   118→

