   199→  </div>
   200→
   201→  <!-- Load Phase 9 modules in dependency order -->
   202→  <script src="src/core/cpu-state.js"></script>
   203→  <script src="src/core/instruction-set.js"></script>
   204→  <script src="src/animation/timing-controller.js"></script>
   205→  <script src="src/animation/animation-engine.js"></script>
   206→  <script src="src/core/sequence-generator.js"></script>
   207→  <script src="src/programs/basic-instructions.js"></script>
   208→  <script src="src/programs/fibonacci.js"></script>
   209→
   210→  <!-- Load Phase 10 visualization modules -->
   211→  <script src="src/visualization/block-diagram-view.js"></script>
   212→  <script src="src/visualization/register-view.js"></script>
   213→  <script src="src/visualization/cpu-visualizer.js"></script>
   214→
   215→  <!-- Test suite and live demo -->
   216→  <script>
   217→    (function() {
   218→      'use strict';
   219→
   220→      // Test framework
   221→      let passCount = 0;
   222→      let failCount = 0;
   223→      const results = [];
   224→
   225→      function test(name, fn) {
   226→        try {
   227→          fn();
   228→          passCount++;
   229→          results.push({ name, pass: true });
   230→        } catch (e) {
   231→          failCount++;
   232→          results.push({ name, pass: false, error: e.message });
   233→        }
   234→      }
   235→
   236→      function assert(condition, message) {
   237→        if (!condition) {
   238→          throw new Error(message || 'Assertion failed');
   239→        }
   240→      }
   241→
   242→      function assertEquals(actual, expected, message) {
   243→        if (actual !== expected) {
   244→          throw new Error(message || `Expected ${expected}, got ${actual}`);
   245→        }
   246→      }
   247→
   248→      function assertGreaterThan(actual, threshold, message) {
   249→        if (actual <= threshold) {
   250→          throw new Error(message || `Expected ${actual} > ${threshold}`);
   251→        }
   252→      }
   253→
   254→      // Live demo state
   255→      let animationEngine = null;
   256→      let visualizer = null;
   257→      let currentProgram = 'basic';
   258→
   259→      // Initialize live demo when DOM is ready
   260→      document.addEventListener('DOMContentLoaded', function() {
   261→        initializeLiveDemo();
   262→        runAllTests();
   263→        displayResults();
   264→      });
   265→
   266→      function initializeLiveDemo() {
   267→        const vizContainer = document.getElementById('viz-container');
   268→        const programSelect = document.getElementById('program-select');
   269→        const btnStepBack = document.getElementById('btn-step-back');
   270→        const btnStepForward = document.getElementById('btn-step-forward');
   271→        const btnReset = document.getElementById('btn-reset');
   272→        const statusEl = document.getElementById('status');
   273→
   274→        // Create visualizer
   275→        visualizer = new CPUVisualizer(vizContainer);
   276→
   277→        // Create animation engine
   278→        animationEngine = new AnimationEngine();
   279→
   280→        // Listen to frame changes to update status
   281→        window.addEventListener('cpu:framechange', function(e) {
   282→          const index = e.detail.index;
   283→          const total = animationEngine.getTotalFrames();
   284→          statusEl.textContent = `Frame ${index} of ${total - 1}`;
   285→        });
   286→
   287→        // Load initial program
   288→        loadProgram(currentProgram);
   289→
   290→        // Wire up controls
   291→        programSelect.addEventListener('change', function() {
   292→          currentProgram = this.value;
   293→          loadProgram(currentProgram);
   294→        });
   295→
   296→        btnStepBack.addEventListener('click', function() {
   297→          animationEngine.stepBackward();
   298→        });
   299→
   300→        btnStepForward.addEventListener('click', function() {
   301→          animationEngine.stepForward();
   302→        });
   303→
   304→        btnReset.addEventListener('click', function() {
   305→          animationEngine.reset();
   306→        });
   307→      }
   308→
   309→      function loadProgram(programName) {
   310→        const program = programName === 'basic' ? BASIC_PROGRAM : FIBONACCI_PROGRAM;
   311→        const result = SequenceGenerator.generateSequence(program.instructions);
   312→        animationEngine.loadFrames(result.frames);
   313→
   314→        const statusEl = document.getElementById('status');
   315→        statusEl.textContent = `Frame 0 of ${result.frames.length - 1}`;
   316→      }
   317→
   318→      function runAllTests() {
   319→        // ============================================
   320→        // BLOCKDIAGRAMVIEW TESTS
   321→        // ============================================
   322→
   323→        test('BlockDiagramView creates SVG element with viewBox', function() {
   324→          const container = document.createElement('div');
   325→          const view = new BlockDiagramView(container);
   326→
   327→          const svg = container.querySelector('svg');
   328→          assert(svg, 'SVG element should exist');
   329→          assert(svg.getAttribute('viewBox'), 'SVG should have viewBox attribute');
   330→        });
   331→
   332→        test('BlockDiagramView renders major hardware components', function() {
   333→          const container = document.createElement('div');
   334→          const view = new BlockDiagramView(container);
   335→
   336→          assert(container.querySelector('[data-component="IMEM"]'), 'IMEM component exists');
   337→          assert(container.querySelector('[data-component="REGFILE"]'), 'REGFILE component exists');
   338→          assert(container.querySelector('[data-component="ALU"]'), 'ALU component exists');
   339→          assert(container.querySelector('[data-component="DMEM"]'), 'DMEM component exists');
   340→        });
   341→
   342→        test('BlockDiagramView renders pipeline registers', function() {
   343→          const container = document.createElement('div');
   344→          const view = new BlockDiagramView(container);
   345→
   346→          assert(container.querySelector('[data-pipeline-reg="FD"]'), 'F/D register exists');
   347→          assert(container.querySelector('[data-pipeline-reg="DX"]'), 'D/X register exists');
   348→          assert(container.querySelector('[data-pipeline-reg="XM"]'), 'X/M register exists');
   349→          assert(container.querySelector('[data-pipeline-reg="MW"]'), 'M/W register exists');
   350→        });
   351→
   352→        test('BlockDiagramView renders multiplexers', function() {
   353→          const container = document.createElement('div');
   354→          const view = new BlockDiagramView(container);
   355→
   356→          const muxes = container.querySelectorAll('[data-mux]');
   357→          assertGreaterThan(muxes.length, 1, 'Should have at least 2 multiplexers');
   358→        });
   359→
   360→        test('BlockDiagramView highlights active components on render', function() {
   361→          const container = document.createElement('div');
   362→          const view = new BlockDiagramView(container);
   363→          const state = CPUState.createInitial();
   364→
   365→          state.pipeline.EX.active = true;
   366→          view.render(state);
   367→
   368→          const alu = container.querySelector('[data-component="ALU"]');
   369→          assert(alu.classList.contains('active'), 'ALU should be highlighted when EX stage is active');
   370→        });
   371→
   372→        test('BlockDiagramView updates pipeline register instruction display', function() {
   373→          const container = document.createElement('div');
   374→          const view = new BlockDiagramView(container);
   375→          const state = CPUState.createInitial();
   376→
   377→          state.pipeline.IF.active = true;
   378→          state.pipeline.IF.instruction = InstructionSet.createInstruction('ADDI', {
   379→            rs: 0, rt: 8, immediate: 10
   380→          });
   381→          view.render(state);
   382→
   383→          const fdDisplay = container.querySelector('[data-instruction-display="FD"]');
   384→          assert(fdDisplay.textContent !== 'NOP', 'F/D register should show instruction (not NOP)');
   385→          assert(fdDisplay.textContent.includes('ADDI'), 'F/D register should show ADDI instruction');
   386→        });
   387→
   388→        test('BlockDiagramView shows NOP when stage is inactive', function() {
   389→          const container = document.createElement('div');
   390→          const view = new BlockDiagramView(container);
   391→          const state = CPUState.createInitial();
   392→
   393→          // All stages inactive
   394→          view.render(state);
   395→
   396→          const displays = container.querySelectorAll('[data-instruction-display]');
   397→          displays.forEach(display => {
   398→            assertEquals(display.textContent, 'NOP', 'Inactive stages should show NOP');
   399→          });
   400→        });
   401→
   402→        // ============================================
   403→        // REGISTERVIEW TESTS
   404→        // ============================================
   405→
   406→        test('RegisterView creates 32 register cells', function() {
   407→          const container = document.createElement('div');
   408→          const view = new RegisterView(container);
   409→
   410→          const cells = container.querySelectorAll('[data-register]');
   411→          assertEquals(cells.length, 32, 'Should have 32 register cells');
   412→
   413→          // Check first and last
   414→          assert(container.querySelector('[data-register="0"]'), 'Register $0 exists');
   415→          assert(container.querySelector('[data-register="31"]'), 'Register $31 exists');
   416→        });
   417→
   418→        test('RegisterView shows hex values', function() {
   419→          const container = document.createElement('div');
   420→          const view = new RegisterView(container);
   421→          const state = CPUState.createInitial();
   422→
   423→          view.render(state);
   424→
   425→          const values = container.querySelectorAll('.register-value');
   426→          values.forEach(el => {
   427→            assert(el.textContent.startsWith('0x'), 'Values should be hex format');
   428→          });
   429→        });
   430→
   431→        test('RegisterView highlights changed registers', function() {
   432→          const container = document.createElement('div');
   433→          const view = new RegisterView(container);
   434→          const state = CPUState.createInitial();
   435→
   436→          // First render to initialize
   437→          view.render(state);
   438→
   439→          // Second render with changes
   440→          state.setRegister(5, 0x12345678);
   441→          state.setRegister(7, 0xABCDEF00);
   442→          view.render(state);
   443→
   444→          const cell5 = container.querySelector('[data-register="5"]');
   445→          const cell7 = container.querySelector('[data-register="7"]');
   446→
   447→          assert(cell5.classList.contains('changed'), 'Register 5 should be highlighted');
   448→          assert(cell7.classList.contains('changed'), 'Register 7 should be highlighted');
   449→
   450→          const value5 = cell5.querySelector('.register-value');
   451→          assertEquals(value5.textContent, '0x12345678', 'Register 5 value should update');
   452→        });
   453→
   454→        test('RegisterView removes highlight on next render', function() {
   455→          const container = document.createElement('div');
   456→          const view = new RegisterView(container);
   457→          const state = CPUState.createInitial();
   458→
   459→          // First render
   460→          view.render(state);
   461→
   462→          // Second render with changes
   463→          state.setRegister(5, 100);
   464→          view.render(state);
   465→
   466→          assert(container.querySelector('[data-register="5"]').classList.contains('changed'),
   467→            'Should have highlight after change');
   468→
   469→          // Third render with no changes
   470→          const state2 = state.clone();
   471→          state2.changedRegisters.clear();
   472→          view.render(state2);
   473→
   474→          assert(!container.querySelector('[data-register="5"]').classList.contains('changed'),
   475→            'Highlight should be removed');
   476→        });
   477→
   478→        test('Register $0 cell exists', function() {
   479→          const container = document.createElement('div');
   480→          const view = new RegisterView(container);
   481→
   482→          const cell0 = container.querySelector('[data-register="0"]');
   483→          assert(cell0, 'Register $0 cell exists');
   484→        });
   485→
   486→        // ============================================
   487→        // CPUVISUALIZER INTEGRATION TESTS
   488→        // ============================================
   489→
   490→        test('CPUVisualizer creates DOM with block diagram and register sections', function() {
   491→          const container = document.createElement('div');
   492→          const visualizer = new CPUVisualizer(container);
   493→
   494→          assert(container.querySelector('[data-block-diagram]'), 'Block diagram container exists');
   495→          assert(container.querySelector('[data-register-view]'), 'Register view container exists');
   496→        });
   497→
   498→        test('CPUVisualizer does NOT create pipeline-view or execution-view', function() {
   499→          const container = document.createElement('div');
   500→          const visualizer = new CPUVisualizer(container);
   501→
   502→          assert(!container.querySelector('[data-pipeline-view]'), 'Pipeline view should NOT exist');
   503→          assert(!container.querySelector('[data-execution-view]'), 'Execution view should NOT exist');
   504→        });
   505→
   506→        test('CPUVisualizer responds to cpu:framechange event', function() {
   507→          const container = document.createElement('div');
   508→          const visualizer = new CPUVisualizer(container);
   509→          const state = CPUState.createInitial();
   510→
   511→          state.pipeline.IF.active = true;
   512→          state.pipeline.IF.instruction = InstructionSet.createInstruction('ADDI', {
   513→            rs: 0, rt: 8, immediate: 42
   514→          });
   515→
   516→          // Dispatch synthetic event
   517→          const event = new CustomEvent('cpu:framechange', {
   518→            detail: { state: state, index: 1, total: 10 }
   519→          });
   520→          window.dispatchEvent(event);
   521→
   522→          // Check if block diagram was updated
   523→          const alu = container.querySelector('[data-component="IMEM"]');
