   532→          const result = SequenceGenerator.generateSequence(BASIC_PROGRAM.instructions);
   533→          engine.loadFrames(result.frames);
   534→
   535→          // Step forward 6 times (through first instruction's WB stage)
   536→          for (let i = 0; i < 6; i++) {
   537→            engine.stepForward();
   538→          }
   539→
   540→          // Check that visualization has active components
   541→          const activeComponents = container.querySelectorAll('.component.active, .multiplexer.active');
   542→          assertGreaterThan(activeComponents.length, 0, 'At least one component should be active');
   543→        });
   544→
   545→        test('CPUVisualizer destroy() cleans up', function() {
   546→          const container = document.createElement('div');
   547→          const visualizer = new CPUVisualizer(container);
   548→
   549→          visualizer.destroy();
   550→
   551→          // Dispatch event after destroy
   552→          const state = CPUState.createInitial();
   553→          const event = new CustomEvent('cpu:framechange', {
   554→            detail: { state: state }
   555→          });
   556→
   557→          // This should not throw an error
   558→          window.dispatchEvent(event);
   559→
   560→          // Container should be empty
   561→          assertEquals(container.innerHTML, '', 'Container should be cleared');
   562→        });
   563→      }
   564→
   565→      function displayResults() {
   566→        const summaryEl = document.getElementById('summary');
   567→        const resultsEl = document.getElementById('results');
   568→
   569→        // Summary
   570→        const total = passCount + failCount;
   571→        if (failCount === 0) {
   572→          summaryEl.className = 'summary success';
   573→          summaryEl.textContent = `✓ All ${total} tests passed!`;
   574→        } else {
   575→          summaryEl.className = 'summary failure';
   576→          summaryEl.textContent = `✗ ${failCount} of ${total} tests failed`;
   577→        }
   578→
   579→        // Group results by component
   580→        const sections = {
   581→          'BlockDiagramView': [],
   582→          'RegisterView': [],
   583→          'CPUVisualizer': []
   584→        };
   585→
   586→        results.forEach(result => {
   587→          if (result.name.includes('BlockDiagramView')) {
   588→            sections['BlockDiagramView'].push(result);
   589→          } else if (result.name.includes('RegisterView')) {
   590→            sections['RegisterView'].push(result);
   591→          } else if (result.name.includes('CPUVisualizer')) {
   592→            sections['CPUVisualizer'].push(result);
   593→          }
   594→        });
   595→
   596→        // Render sections
   597→        Object.keys(sections).forEach(sectionName => {
   598→          if (sections[sectionName].length === 0) return;
   599→
   600→          const sectionDiv = document.createElement('div');
   601→          sectionDiv.className = 'test-section';
   602→
   603→          const title = document.createElement('h3');
   604→          title.textContent = sectionName + ' Tests';
   605→          sectionDiv.appendChild(title);
   606→
   607→          sections[sectionName].forEach(result => {
   608→            const item = document.createElement('div');
   609→            item.className = 'test-item ' + (result.pass ? 'pass' : 'fail');
   610→
   611→            const label = document.createElement('span');
   612→            label.className = 'label';
   613→            label.textContent = result.pass ? 'PASS' : 'FAIL';
   614→            item.appendChild(label);
   615→
   616→            const name = document.createTextNode(result.name);
   617→            item.appendChild(name);
   618→
   619→            if (!result.pass && result.error) {
   620→              const error = document.createElement('div');
   621→              error.className = 'error-details';
   622→              error.textContent = result.error;
   623→              item.appendChild(error);
   624→            }
   625→
   626→            sectionDiv.appendChild(item);
   627→          });
   628→
   629→          resultsEl.appendChild(sectionDiv);
   630→        });
   631→      }
   632→    })();
