let animationEngine = null;
let visualizer = null;
let currentProgram = 'basic';

// Initialize live demo when DOM is ready
document.addEventListener('DOMContentLoaded', function() {
  initializeLiveDemo();
  runAllTests();
  displayResults();
});

function initializeLiveDemo() {
  const vizContainer = document.getElementById('viz-container');
  const programSelect = document.getElementById('program-select');
  const btnStepBack = document.getElementById('btn-step-back');
  const btnStepForward = document.getElementById('btn-step-forward');
  const btnReset = document.getElementById('btn-reset');
  const statusEl = document.getElementById('status');

  // Create visualizer
  visualizer = new CPUVisualizer(vizContainer);

  // Create animation engine
  animationEngine = new AnimationEngine();

  // Listen to frame changes to update status
  window.addEventListener('cpu:framechange', function(e) {
    const index = e.detail.index;
    const total = animationEngine.getTotalFrames();
    statusEl.textContent = `Frame ${index} of ${total - 1}`;
  });

  // Load initial program
  loadProgram(currentProgram);

  // Wire up controls
  programSelect.addEventListener('change', function() {
    currentProgram = this.value;
    loadProgram(currentProgram);
  });

  btnStepBack.addEventListener('click', function() {
    animationEngine.stepBackward();
  });

  btnStepForward.addEventListener('click', function() {
    animationEngine.stepForward();
  });

  btnReset.addEventListener('click', function() {
    animationEngine.reset();
  });
}

function loadProgram(programName) {
  const program = programName === 'basic' ? BASIC_PROGRAM : FIBONACCI_PROGRAM;
  const result = SequenceGenerator.generateSequence(program.instructions);
  animationEngine.loadFrames(result.frames);

  const statusEl = document.getElementById('status');
  statusEl.textContent = `Frame 0 of ${result.frames.length - 1}`;
}

