    assert(fdDisplay.textContent !== 'NOP', 'F/D register should show instruction (not NOP)');
    assert(fdDisplay.textContent.includes('ADDI'), 'F/D register should show ADDI instruction');
  });

  test('BlockDiagramView shows NOP when stage is inactive', function() {
    const container = document.createElement('div');
    const view = new BlockDiagramView(container);
    const state = CPUState.createInitial();

    // All stages inactive
    view.render(state);

    const displays = container.querySelectorAll('[data-instruction-display]');
    displays.forEach(display => {
      assertEquals(display.textContent, 'NOP', 'Inactive stages should show NOP');
    });
  });

  // ============================================
  // REGISTERVIEW TESTS
  // ============================================

  test('RegisterView creates 32 register cells', function() {
    const container = document.createElement('div');
    const view = new RegisterView(container);

    const cells = container.querySelectorAll('[data-register]');
    assertEquals(cells.length, 32, 'Should have 32 register cells');

    // Check first and last
    assert(container.querySelector('[data-register="0"]'), 'Register $0 exists');
    assert(container.querySelector('[data-register="31"]'), 'Register $31 exists');
  });

  test('RegisterView shows hex values', function() {
    const container = document.createElement('div');
    const view = new RegisterView(container);
    const state = CPUState.createInitial();

    view.render(state);

    const values = container.querySelectorAll('.register-value');
    values.forEach(el => {
      assert(el.textContent.startsWith('0x'), 'Values should be hex format');
    });
  });

  test('RegisterView highlights changed registers', function() {
    const container = document.createElement('div');
    const view = new RegisterView(container);
    const state = CPUState.createInitial();

    // First render to initialize
    view.render(state);

    // Second render with changes
    state.setRegister(5, 0x12345678);
    state.setRegister(7, 0xABCDEF00);
    view.render(state);

    const cell5 = container.querySelector('[data-register="5"]');
    const cell7 = container.querySelector('[data-register="7"]');

    assert(cell5.classList.contains('changed'), 'Register 5 should be highlighted');
    assert(cell7.classList.contains('changed'), 'Register 7 should be highlighted');

    const value5 = cell5.querySelector('.register-value');
    assertEquals(value5.textContent, '0x12345678', 'Register 5 value should update');
  });

  test('RegisterView removes highlight on next render', function() {
    const container = document.createElement('div');
    const view = new RegisterView(container);
    const state = CPUState.createInitial();

    // First render
    view.render(state);

    // Second render with changes
    state.setRegister(5, 100);
    view.render(state);

    assert(container.querySelector('[data-register="5"]').classList.contains('changed'),
      'Should have highlight after change');

    // Third render with no changes
    const state2 = state.clone();
    state2.changedRegisters.clear();
    view.render(state2);

    assert(!container.querySelector('[data-register="5"]').classList.contains('changed'),
      'Highlight should be removed');
  });

  test('Register $0 cell exists', function() {
    const container = document.createElement('div');
    const view = new RegisterView(container);

    const cell0 = container.querySelector('[data-register="0"]');
    assert(cell0, 'Register $0 cell exists');
  });

  // ============================================
  // CPUVISUALIZER INTEGRATION TESTS
  // ============================================

  test('CPUVisualizer creates DOM with block diagram and register sections', function() {
    const container = document.createElement('div');
    const visualizer = new CPUVisualizer(container);

    assert(container.querySelector('[data-block-diagram]'), 'Block diagram container exists');
    assert(container.querySelector('[data-register-view]'), 'Register view container exists');
  });

  test('CPUVisualizer does NOT create pipeline-view or execution-view', function() {
    const container = document.createElement('div');
    const visualizer = new CPUVisualizer(container);

    assert(!container.querySelector('[data-pipeline-view]'), 'Pipeline view should NOT exist');
    assert(!container.querySelector('[data-execution-view]'), 'Execution view should NOT exist');
  });

  test('CPUVisualizer responds to cpu:framechange event', function() {
    const container = document.createElement('div');
    const visualizer = new CPUVisualizer(container);
    const state = CPUState.createInitial();

    state.pipeline.IF.active = true;
    state.pipeline.IF.instruction = InstructionSet.createInstruction('ADDI', {
      rs: 0, rt: 8, immediate: 42
    });

    // Dispatch synthetic event
    const event = new CustomEvent('cpu:framechange', {
      detail: { state: state, index: 1, total: 10 }
    });
    window.dispatchEvent(event);

    // Check if block diagram was updated
    const alu = container.querySelector('[data-component="IMEM"]');
    assert(alu, 'Components should be rendered');
  });

  test('CPUVisualizer full program playback', function() {
    const container = document.createElement('div');
    const visualizer = new CPUVisualizer(container);
    const engine = new AnimationEngine();

    const result = SequenceGenerator.generateSequence(BASIC_PROGRAM.instructions);
    engine.loadFrames(result.frames);

    // Step forward 6 times (through first instruction's WB stage)
    for (let i = 0; i < 6; i++) {
      engine.stepForward();
    }

    // Check that visualization has active components
    const activeComponents = container.querySelectorAll('.component.active, .multiplexer.active');
    assertGreaterThan(activeComponents.length, 0, 'At least one component should be active');
  });

  test('CPUVisualizer destroy() cleans up', function() {
    const container = document.createElement('div');
    const visualizer = new CPUVisualizer(container);

    visualizer.destroy();

    // Dispatch event after destroy
    const state = CPUState.createInitial();
    const event = new CustomEvent('cpu:framechange', {
      detail: { state: state }
    });

    // This should not throw an error
    window.dispatchEvent(event);

    // Container should be empty
    assertEquals(container.innerHTML, '', 'Container should be cleared');
  });
}

function displayResults() {
  const summaryEl = document.getElementById('summary');
  const resultsEl = document.getElementById('results');

  // Summary
  const total = passCount + failCount;
  if (failCount === 0) {
    summaryEl.className = 'summary success';
    summaryEl.textContent = `✓ All ${total} tests passed!`;
  } else {
    summaryEl.className = 'summary failure';
    summaryEl.textContent = `✗ ${failCount} of ${total} tests failed`;
  }

  // Group results by component
  const sections = {
    'BlockDiagramView': [],
    'RegisterView': [],
    'CPUVisualizer': []
  };

  results.forEach(result => {
    if (result.name.includes('BlockDiagramView')) {
      sections['BlockDiagramView'].push(result);
    } else if (result.name.includes('RegisterView')) {
      sections['RegisterView'].push(result);
    } else if (result.name.includes('CPUVisualizer')) {
      sections['CPUVisualizer'].push(result);
    }
  });

  // Render sections
  Object.keys(sections).forEach(sectionName => {
    if (sections[sectionName].length === 0) return;

    const sectionDiv = document.createElement('div');
    sectionDiv.className = 'test-section';

    const title = document.createElement('h3');
    title.textContent = sectionName + ' Tests';
    sectionDiv.appendChild(title);

    sections[sectionName].forEach(result => {
      const item = document.createElement('div');
      item.className = 'test-item ' + (result.pass ? 'pass' : 'fail');

      const label = document.createElement('span');
      label.className = 'label';
      label.textContent = result.pass ? 'PASS' : 'FAIL';
      item.appendChild(label);

      const name = document.createTextNode(result.name);
      item.appendChild(name);

      if (!result.pass && result.error) {
        const error = document.createElement('div');
        error.className = 'error-details';
        error.textContent = result.error;
        item.appendChild(error);
      }

      sectionDiv.appendChild(item);
    });

    resultsEl.appendChild(sectionDiv);
  });
}

