/* Test results styles */
.summary {
  font-size: 18px;
  padding: 15px;
  margin: 20px 0;
  border-radius: 4px;
  font-weight: bold;
}

.summary.success {
  background: #d4edda;
  color: #155724;
  border: 1px solid #c3e6cb;
}

.summary.failure {
  background: #f8d7da;
  color: #721c24;
  border: 1px solid #f5c6cb;
}

.test-section {
  margin-bottom: 30px;
}

.test-section h3 {
  font-size: 18px;
  color: #495057;
  margin-bottom: 10px;
  padding-bottom: 5px;
  border-bottom: 2px solid #dee2e6;
}

.test-item {
  padding: 8px 12px;
  margin: 4px 0;
  border-radius: 4px;
  font-size: 14px;
}

.test-item.pass {
  background: #d4edda;
  color: #155724;
}

.test-item.fail {
  background: #f8d7da;
  color: #721c24;
}

.test-item .label {
  font-weight: bold;
  margin-right: 8px;
}

.error-details {
  margin-top: 4px;
  padding: 8px;
  background: #fff;
  border-left: 3px solid #dc3545;
  font-size: 12px;
  color: #6c757d;
}

.loading {
  text-align: center;
  padding: 40px;
  color: #6c757d;
  font-size: 16px;
}

/* Visualization container styling */
#viz-container {
  margin-top: 20px;
  min-height: 400px;
}

